{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Timolol, which shares the identical tert-butylamino-2-hydroxypropoxy aryl ether side chain as the query, has an absolute oral bioavailability of 61.0 ± 19.2% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, another aryloxypropanolamine beta-blocker, has an absolute oral bioavailability of 38 ± 14% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Propranolol, a high-first-pass beta-blocker, has an absolute oral bioavailability of 30% in normal subjects, supporting F ≥ 20% despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Encainide, a basic aromatic drug with extensive first-pass metabolism, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20% for similarly metabolized basic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Flecainide, a basic aromatic drug with a piperidine side chain, has an absolute oral bioavailability of 70% in healthy volunteers, supporting high F for the query's drug-like basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "One propranolol study reported 19% oral bioavailability in healthy volunteers, below the 20% threshold; this is an outlier against the many higher propranolol values and does not overturn the high prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a tert-butylamino-hydroxypropoxy aryl ether beta-blocker analogue. Close structural relatives timolol (61% absolute F), metoprolol (38%), and propranolol (30%) all show oral bioavailability at or above 20%, with only a single 19% propranolol observation below threshold. The weight of high-transfer experimental evidence supports high bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "The para-urea-cyclohexyl substituent is not directly represented in the analogue set; its effect on first-pass metabolism and permeability is inferred.",
    "Interindividual variability in first-pass metabolism could place some individuals below 20%, but population means from close analogues support high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

